-- Global discovery, using query parameters generated by patent_query_plan.py.
-- Publication dates use [start_date, end_date). No silent LIMIT truncation.
-- Run a dry run and enforce maximumBytesBilled before executing this query.
WITH candidates AS (
  SELECT
    p.publication_number, p.application_number, p.family_id,
    p.country_code, p.kind_code,
    SAFE.PARSE_DATE('%Y%m%d', CAST(p.filing_date AS STRING)) AS filing_date,
    SAFE.PARSE_DATE('%Y%m%d', CAST(p.priority_date AS STRING)) AS priority_date,
    SAFE.PARSE_DATE('%Y%m%d', CAST(p.publication_date AS STRING)) AS publication_date,
    COALESCE(
      (SELECT text FROM UNNEST(p.title_localized) WHERE language = 'en' LIMIT 1),
      (SELECT text FROM UNNEST(p.title_localized) LIMIT 1)
    ) AS title,
    ARRAY(SELECT code FROM UNNEST(p.cpc)) AS cpc_codes,
    ARRAY(SELECT name FROM UNNEST(p.assignee_harmonized)) AS assignees
  FROM `patents-public-data.patents.publications` p
  WHERE SAFE.PARSE_DATE('%Y%m%d', CAST(p.publication_date AS STRING)) >= @start_date
    AND SAFE.PARSE_DATE('%Y%m%d', CAST(p.publication_date AS STRING)) < @end_date
)
SELECT c.* FROM candidates c
WHERE EXISTS (
  SELECT 1 FROM UNNEST(c.assignees) a
  WHERE TRIM(REGEXP_REPLACE(REGEXP_REPLACE(NORMALIZE_AND_CASEFOLD(a, NFKC),
    r'[^\p{L}\p{N}]', ' '), r'\s+', ' ')) IN UNNEST(@company_names)
)
OR EXISTS (
  SELECT 1 FROM UNNEST(c.cpc_codes) code CROSS JOIN UNNEST(@cpc_prefixes) prefix
  WHERE STARTS_WITH(REGEXP_REPLACE(UPPER(code), r'[ /]', ''), prefix)
)
OR EXISTS (
  SELECT 1 FROM UNNEST(@technology_terms) term
  WHERE STRPOS(CONCAT(' ', TRIM(REGEXP_REPLACE(REGEXP_REPLACE(
    NORMALIZE_AND_CASEFOLD(c.title, NFKC), r'[^\p{L}\p{N}]', ' '), r'\s+', ' ')), ' '),
    CONCAT(' ', term, ' ')) > 0
);
